css:
@page {
  size: A4;
  margin: 5mm;
}

:root {
  --brand: #0f766e;
  --soft: #e7f4f2;
  --soft-2: #f3faf9;
  --ink: #12212b;
  --muted: #58707d;
  --line: #d5dde2;
  --card: #ffffff;
}

@font-face {
  font-family: 'Noto Naskh Arabic';
  src: url('/assets/tms/fonts/NotoNaskhArabic-VariableFont_wght.ttf') format('truetype');
  font-weight: 400 700;
  font-style: normal;
}

body {
  font-family: 'Ubuntu', 'Segoe UI', Arial, sans-serif;
  font-size: 8.2px;
  color: var(--ink);
}

.print-format {
  padding: 2mm !important;
  border-radius: 0 !important;
}

* {
  box-sizing: border-box;
}

.po-format,
.sheet {
  width: 100%;
  background: #ffffff;
}

/* Header */
.company-header-box {
  width: 100%;
  border-bottom: 1px solid var(--line);
  padding-bottom: 5px;
  margin-bottom: 5px;
}

.company-header-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.company-header-table td {
  vertical-align: top !important;
  border: 0 !important;
  padding: 0 !important;
}

.company-info-en {
  width: 36%;
  text-align: left;
  direction: ltr;
  font-size: 9.4px;
  line-height: 1.32;
}

.company-info-ar {
  width: 36%;
  text-align: right;
  direction: rtl;
  font-family: 'Noto Naskh Arabic', serif;
  font-size: 9.5px;
  line-height: 1.32;
}

.company-logo-mid {
  width: 24%;
  text-align: center;
  vertical-align: middle !important;
}

.company-name-en {
  font-size: 12.2px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-name-ar {
  font-size: 12.8px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-line {
  margin-bottom: 1.5px;
}

.company-label {
  font-weight: 600;
  color: var(--brand);
}

.brand-logo-frame {
  display: inline-block;
  min-width: 150px;
  min-height: 78px;
  text-align: center;
}

.brand-logo {
  display: block;
  max-width: 138px !important;
  max-height: 92px !important;
  width: auto !important;
  height: auto !important;
  margin: 0 auto;
  object-fit: contain;
}

.brand-logo-fallback {
  display: inline-block;
  margin-top: 18px;
  color: var(--brand);
  font-size: 20px;
  font-weight: 700;
}

.invoice-title-center {
  text-align: center;
  font-size: 13.5px;
  font-weight: 700;
  margin-top: 3px;
  color: var(--brand);
  line-height: 1.15;
}

.arabic-title {
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  font-size: 12px;
}

/* PO Meta right side */
.po-meta-grid {
  width: 100%;
  border-collapse: collapse;
  margin: 2px 0 5px 0;
}

.po-meta-grid td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}

.po-meta-left {
  width: 50%;
}

.po-meta-card {
  width: 50%;
}

.po-meta-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.po-meta-table td {
  border-bottom: 1px dashed var(--line) !important;
  padding: 2px 3px !important;
  line-height: 1.14;
  vertical-align: top !important;
}

.po-meta-table tr:last-child td {
  border-bottom: 0 !important;
}

.po-meta-table td:first-child {
  width: 40%;
  color: var(--brand);
  font-weight: 700;
  text-align: left;
}

.po-meta-table td:nth-child(2) {
  width: 38%;
  text-align: center;
  font-weight: 700;
  color: #111;
}

.po-meta-table td:last-child {
  width: 38%;
  text-align: right;
  direction: rtl;
  color: var(--muted);
  font-family: 'Noto Naskh Arabic', serif;
}

/* Supplier + Bill To */
.party-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 3px;
}

.party-grid > tbody > tr > td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}

.party-column {
  width: 49%;
}

.party-gap,
.summary-spacer {
  width: 2%;
}

.party-card {
  width: 100%;
  background: var(--card);
  border: 0 !important;
  border-top: 1px solid var(--line) !important;
  padding: 3px 0 0 !important;
  page-break-inside: avoid;
}

.party-title {
  display: table;
  width: 100%;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 3px;
}

.party-title strong {
  display: table-cell;
  color: var(--brand);
  font-size: 7.8px;
  font-weight: 700;
  text-transform: uppercase;
}

.party-title span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  text-align: right;
  color: var(--muted);
  font-size: 8px;
}

.party-rows {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.party-rows td {
  padding: 1.8px 0 !important;
  border-bottom: 1px dashed var(--line) !important;
  vertical-align: top !important;
  line-height: 1.16;
}

.party-rows tr:last-child td {
  border-bottom: 0 !important;
}

.party-rows td:first-child {
  width: 28%;
  color: var(--muted);
  font-weight: 600;
}

.party-rows td:nth-child(2) {
  width: 46%;
  font-weight: 500;
  padding-right: 8px !important;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.party-rows td:last-child {
  font-family: 'Noto Naskh Arabic', serif;
  width: 26%;
  direction: rtl;
  text-align: right;
  color: var(--muted);
}

/* Blocks */
.block {
  margin-top: 5px;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  padding: 3px 0 0;
}

.block-head {
  display: table;
  width: 100%;
  margin-bottom: 3px;
}

.block-head strong {
  display: table-cell;
  color: var(--brand);
  font-size: 7.5px;
  font-weight: 700;
  text-transform: uppercase;
}

.block-head span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  text-align: right;
  color: var(--muted);
  font-size: 7.8px;
}

/* Items */
.items-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.items-table th,
.items-table td {
  border: 1px solid var(--line);
  padding: 2.5px 4px !important;
  vertical-align: top !important;
  line-height: 1.16;
}

.items-table thead th {
  background: var(--soft);
  color: var(--brand);
  font-size: 7.2px;
  font-weight: 700;
  text-transform: uppercase;
  text-align: center;
}

.item-desc-cell {
  font-size: 8.6px;
  line-height: 1.18;
  overflow-wrap: break-word;
}

.item-main {
  font-weight: 700;
  color: #111827;
}

.num {
  text-align: right;
  direction: ltr;
  white-space: nowrap;
}

.center {
  text-align: center;
}

/* Totals */
.totals-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 4px;
  margin-top: 2px;
}

.tax-card,
.totals-card {
  width: 49%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  padding: 3px 0 0;
}

.section-kicker {
  color: var(--brand);
  font-weight: 700;
  font-size: 7.4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 3px;
}

.tax-table,
.totals-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.tax-table th,
.tax-table td,
.totals-table td {
  border: 1px solid var(--line);
  padding: 2.5px 4px !important;
  line-height: 1.15;
}

.tax-table th {
  background: var(--soft-2);
  color: var(--brand);
  text-align: left;
  font-size: 7.2px;
  font-weight: 700;
}

.totals-table td:first-child {
  color: var(--muted);
  font-weight: 600;
}

.totals-table td:last-child,
.tax-table td.num,
.tax-table td:last-child {
  text-align: right;
  direction: ltr;
}

.grand-row td {
  background: var(--brand);
  color: #ffffff !important;
  font-weight: 700 !important;
}

/* In Words */
.footnote {
  margin-top: 4px;
  border-top: 1px dashed var(--line);
  border-bottom: 1px dashed var(--line);
  padding: 4px 0;
  color: #111827;
  line-height: 1.3;
}

/* Terms page */
.terms-page {
  page-break-before: always !important;
  break-before: page !important;
  padding-top: 3mm;
}

.terms-box {
  border: 1px solid #222 !important;
  padding: 8px 8px 12px 8px !important;
  min-height: 265mm !important;
  position: relative;
  page-break-inside: avoid;
}

.terms-title {
  font-size: 10.5px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.03em;
  margin-bottom: 8px !important;
  color: #111 !important;
}

.terms-content {
  font-size: 8.7px !important;
  line-height: 1.28 !important;
  color: #111 !important;
}

.terms-content .ql-editor {
  padding: 0 !important;
}

.terms-content h1,
.terms-content h2,
.terms-content h3 {
  font-size: 9.5px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  margin: 8px 0 4px 0 !important;
  padding: 0 !important;
  line-height: 1.15 !important;
  color: #111 !important;
}

.terms-content p {
  margin: 0 0 2px 0 !important;
  padding: 0 !important;
}

.terms-content br {
  display: none !important;
}

.terms-content div {
  line-height: 1.28;
}

/* Signature on terms page bottom */
.signature-table {
  width: 100%;
  border-collapse: collapse;
}

.terms-signature {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 10px;
  width: calc(100% - 16px);
}

.signature-table td {
  width: 33.33%;
  text-align: center;
  border: 0 !important;
  padding: 14px 14px 0 14px !important;
  color: var(--muted);
}

.sign-line {
  border-top: 1px solid #333;
  margin-bottom: 4px;
}

/* PDF safety */
.company-header-box,
.po-meta-grid,
.party-grid,
.totals-grid,
.footnote {
  page-break-inside: avoid;
  break-inside: avoid;
}

.items-table tr {
  page-break-inside: avoid;
  break-inside: avoid;
}

[dir="rtl"],
.company-info-ar,
.company-name-ar,
.po-meta-table td:last-child,
.party-title span,
.party-rows td:last-child,
.block-head span,
.arabic-title {
  font-family: 'Noto Naskh Arabic', serif !important;
}

/* Full width PO meta table */
.po-meta-full {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin: 3px 0 6px 0;
  page-break-inside: avoid;
}

.po-meta-full td {
  border: 1px solid var(--line) !important;
  padding: 3px 5px !important;
  line-height: 1.15;
  vertical-align: middle !important;
  white-space: nowrap !important;
  overflow: hidden;
  text-overflow: ellipsis;
}

.po-meta-label {
  width: 10%;
  background: var(--soft);
  color: var(--brand);
  font-weight: 700;
  text-align: left;
}

.po-meta-value {
  width: 22%;
  color: #111;
  font-weight: 700;
  text-align: left;
}
